link_wrappers.text:
#!/usr/bin/env python3
import os
from pathlib import Path
import sys

args = sys.argv[1:]
if args[:2] == ['-flavor', 'gnu']:
    args = args[2:]
ld_args = []
for arg in args:
    if arg.startswith('-Wl,'):
        ld_args.extend(arg[4:].split(','))
    else:
        ld_args.append(arg)
linker = Path(__file__).with_name('x86_64-breenix-hosted-link-inner')
os.execv(linker, [str(linker), *ld_args])
